package main

import (
	"fmt"
)

const MOD = 1000000007

func modPow(a, e int64) int64 {
	res := int64(1)
	a %= MOD
	for e > 0 {
		if e&1 == 1 {
			res = res * a % MOD
		}
		a = a * a % MOD
		e >>= 1
	}
	return res
}

type State struct {
	dp  [11][11][2]int64
	vis [11][11][2]bool
}

func solve(digits []int, pos int, tight int, cnt int) int64 {
	if pos == len(digits) {
		if cnt >= 0 && cnt <= 10 {
			return 1
		}
		return 0
	}
	st := &State{}
	if st.vis[pos][cnt][tight] {
		return st.dp[pos][cnt][tight]
	}
	st.vis[pos][cnt][tight] = true
	limit := 9
	if tight == 1 {
		limit = digits[pos]
	}
	var res int64
	for d := 0; d <= limit; d++ {
		ntight := 0
		if tight == 1 && d == limit {
			ntight = 1
		}
		ncnt := cnt
		if d == 4 || d == 7 {
			ncnt++
		}
		if ncnt <= 10 {
			res = (res + solve(digits, pos+1, ntight, ncnt)) % MOD
		}
	}
	st.dp[pos][cnt][tight] = res
	return res
}

func countLuckyUpTo(m int) [11]int64 {
	if m < 0 {
		var zero [11]int64
		return zero
	}
	digits := []int{}
	for m > 0 {
		digits = append([]int{m % 10}, digits...)
		m /= 10
	}
	if len(digits) == 0 {
		digits = []int{0}
	}
	var st State
	_ = solve(digits, 0, 1, 0)
	var res [11]int64
	for c := 0; c <= 10; c++ {
		res[c] = st.dp[0][c][1]
	}
	return res
}

func main() {
	var m int
	fmt.Scan(&m)

	freqAll := countLuckyUpTo(m)
	freqZero := countLuckyUpTo(0)
	var freq [11]int64
	for i := 0; i <= 10; i++ {
		freq[i] = (freqAll[i] - freqZero[i] + MOD) % MOD
	}

	invFact := [7]int64{}
	fact := [7]int64{1, 1, 2, 6, 24, 120, 720}
	for i := 0; i <= 6; i++ {
		invFact[i] = modPow(int64(fact[i]), MOD-2)
	}

	var ans int64
	for k := 1; k <= 10; k++ {
		if freq[k] == 0 {
			continue
		}
		freqCopy := freq
		freqCopy[k]--

		dp := [7][11]int64{}
		dp[0][0] = 1

		for c := 0; c <= 10; c++ {
			if freqCopy[c] == 0 {
				continue
			}
			vals := make([]int64, 7)
			vals[0] = 1
			for t := 1; t <= 6; t++ {
				if t > freqCopy[c] {
					break
				}
				// C(freqCopy[c], t)
				comb := freqCopy[c]
				for i := 1; i < t; i++ {
					comb = comb * (freqCopy[c] - int64(i)) % MOD
				}
				comb = comb * invFact[t] % MOD
				vals[t] = comb
			}
			for i := 6; i >= 0; i-- {
				for s := 10; s >= 0; s-- {
					if dp[i][s] == 0 {
						continue
					}
					for t := 1; t <= 6-i; t++ {
						if vals[t] == 0 {
							break
						}
						ns := s + t*c
						if ns > 10 {
							continue
						}
						dp[i+t][ns] = (dp[i+t][ns] + dp[i][s]*vals[t]) % MOD
					}
				}
			}
		}

		var sumWays int64
		for s := 0; s < k; s++ {
			sumWays = (sumWays + dp[6][s]) % MOD
		}
		ans = (ans + freq[k]*sumWays%MOD*720) % MOD
	}
	fmt.Println(ans)
}
